callGraph.callee:
[
      ...workMemories.map((item) => ({
        ...item,
        memoryType: 'work' as const,
        governance: memoryGovernanceFrom(item.metadata) ?? null,
      })),
      ...experiences.map((item) => ({
        ...item,
        memoryType: 'experience' as const,
        governance: memoryGovernanceFrom(item.evidence) ?? null,
      })),
    ].sort

items
      .map((item) => {
        const display = (value: unknown): string | undefined => {
          if (
            typeof value === 'string' ||
            typeof value === 'number' ||
            typeof value === 'boolean'
          ) {
            return String(value);
          }
          return undefined;
        };
        const date =
          item.createdAt instanceof Date
            ? item.createdAt.toISOString().slice(0, 10)
            : (display(item.createdAt) ?? '').slice(0, 10);
        const productName = display(item.productName);
        const taskType = display(item.taskType) ?? 'unknown';
        const status = display(item.status) ?? 'unknown';
        const score = display(item.score);
        const reviewStatus = display(item.reviewStatus);
        return [
          date,
          productName ? `product=${productName}` : undefined,
          `task=${taskType}`,
          `status=${status}`,
          score ? `score=${score}` : undefined,
          reviewStatus ? `review=${reviewStatus}` : undefined,
        ]
          .filter(Boolean)
          .join(' ');
      })
      .join
